def _heads(k):
    """« What CPI measures », « How CPI moves futures », « Trading around CPI », in the three languages."""
    n, pl = NAMES[k]
    de = lambda x: "du " + x[3:] if x.startswith("le ") else "des " + x[4:] if x.startswith("les ") else "de " + x   # FR « du », « des », « de l’ »
    del_ = lambda x: "del " + x[3:] if x.startswith("el ") else "de " + x                                               # ES « del »
    if k == "fomc": m = T("What the FOMC decides", "Ce que décide le FOMC", "Qué decide el FOMC")
    else: m = T(f"What {n['en']} measure{'' if pl else 's'}", f"Ce que mesure{'nt' if pl else ''} {n['fr']}", f"Qué mide{'n' if pl else ''} {n['es']}")
    h = T(f"How {n['en']} move{'' if pl else 's'} futures", f"Comment {n['fr']} {'font' if pl else 'fait'} bouger les futures", f"Cómo mueve{'n' if pl else ''} {n['es']} los futuros")
    a = T(f"Trading around {n['en']}", f"Trader autour {de(n['fr'])}", f"Operar alrededor {del_(n['es'])}")
    return m, h, a

def _hm(hm, lang):
    """« 8:30 a.m. », « 8 h 30 », « 8:30 » from « 08:30 »."""
    h, m = int(hm[:2]), int(hm[3:])
    if lang == "en": return f"{h % 12 or 12}:{m:02d} {'a.m.' if h < 12 else 'p.m.'}"
    if lang == "fr": return f"{h} h {m:02d}" if m else f"{h} h"
    return f"{h}:{m:02d}"


OF = {"retail": T("Retail Sales", "des ventes au détail", "de las ventas minoristas"), "gdp": T("GDP", "du PIB", "del PIB")}   # « Dates de publication du PIB »
GDP_EST = {"GDP q/q (Advance)": T("GDP (Advance)", "PIB (première estimation)", "PIB (avance)"), "GDP q/q (Second Estimate)": T("GDP (Second Estimate)", "PIB (deuxième estimation)", "PIB (segunda estimación)"),
           "GDP q/q (Third Estimate)": T("GDP (Third Estimate)", "PIB (troisième estimation)", "PIB (tercera estimación)")}
def _name(t, x): return t(x) if isinstance(x, dict) else x

def make_release(key):
    k, sl, names, title, what, src = next(r for r in REL if r[0] == key)
    CRUMBS[sl] = title
    evs = sorted([e for e in _EV if e["event"] in names], key=lambda e: (e["date"], e["time"]))
    SYSTEM_PAGES.add(sl)
    def page(lang, t):
        ti = _name(t, title); of = t(OF[k]) if k in OF else ti
        nxt = next((e for e in evs if e["date"] >= TODAY_ISO), None)   # at build; the page picks it again in the browser (NEXT_JS)
        hero = ui.hero(t, T("Economic calendar","Calendrier économique","Calendario económico"), T(f"{ti} release dates 2026–2027.", f"Dates de publication {of} 2026–2027.", f"Fechas de publicación {of} 2026–2027."), what)
        nx = ""
        if nxt:
            nx = (f'<div class="nextrel reveal"><span class="eyebrow">{t(T("Next release","Prochaine publication","Próxima publicación"))}</span>'
                  f'<b class="num" data-nx="when">{_date(t,nxt["date"])} · {nxt["time"]} ET</b><span class="st st-{nxt["status"]}" data-nx="st">{t(STATUS[nxt["status"]])}</span></div>')
        cols = 3 + (k == "gdp")
        rows, year = "", None
        for e in evs:
            if e["date"][:4] != year:   # one group per year
                year = e["date"][:4]; rows += f'<tr class="grp"><th colspan="{cols}">{year}</th></tr>'
            past = e["date"] < TODAY_ISO
            lbl = t(GDP_EST[e["event"]]) if k == "gdp" and e["event"] in GDP_EST else ""
            rows += (f'<tr class="{"past" if past else ""}" data-d="{e["date"]}T{e["time"]}"><th scope="row" class="num">{_date(t,e["date"])}</th><td class="num">{e["time"]} ET</td>'
                     f'{f"<td>{lbl}</td>" if k=="gdp" else ""}<td><span class="st st-{e["status"]}">{t(STATUS[e["status"]])}</span></td></tr>')
        head = f'<tr><th scope="col">{t(T("Date","Date","Fecha"))}</th><th scope="col">{t(T("Time","Heure","Hora"))}</th>{"<th scope=col>"+t(T("Estimate","Estimation","Estimación"))+"</th>" if k=="gdp" else ""}<th scope="col">{t(T("Status","Statut","Estado"))}</th></tr>'
        tbl = f'<div class="cmp-wrap"><table class="cmp reltbl"><thead>{head}</thead><tbody>{rows}</tbody></table></div>'
        note = T(f"Times in New York time (ET). Source: {src}. “Estimated” dates are projected from the usual release pattern: check the official calendar closer to the date. Not financial advice.",
                 f"Heures de New York (ET). Source : {src}. Les dates « estimées » sont projetées selon le calendrier habituel : vérifie le calendrier officiel à l’approche. Ce n’est pas un conseil financier.",
                 f"Horas de Nueva York (ET). Fuente: {src}. Las fechas «estimadas» se proyectan según el patrón habitual: verifica el calendario oficial cuando se acerque. No es asesoramiento financiero.")
        why = T(f"Releases like {ti} can move NQ, ES, yields and the dollar within seconds. Sweep marks every high-impact release on your calendar, warns you in the trade ticket when one is close, and shows how you trade around them.",
                "Des publications comme celle-ci peuvent faire bouger NQ, ES, les taux et le dollar en quelques secondes. Sweep marque chaque annonce importante dans ton calendrier, t’avertit dans le ticket quand une approche, et montre comment tu trades autour.",
                "Datos como este pueden mover NQ, ES, los rendimientos y el dólar en segundos. Sweep marca cada dato importante en tu calendario, te avisa en el ticket cuando se acerca uno y muestra cómo operas a su alrededor.")
        others = (f'<div class="chiprow" style="margin-top:40px"><span class="eyebrow">{t(T("Other releases","Autres publications","Otros datos"))}</span>'
                  + "".join(f'<a class="chip" href="{href(lang,r[1])}">{_name(t, r[3])}</a>' for r in REL if r[0] != k) + "</div>")
        when = max(set(e["time"] for e in evs), key=lambda x: sum(1 for e in evs if e["time"] == x))   # its usual time
        hm, hh, ha = _heads(k)
        art = (f'<h2>{t(hm)}</h2>{t(MEASURE[k])}<h2>{t(hh)}</h2>{t(REACT[k])}'
               f'<h2>{t(ha)}</h2>{localize(lang, t(AROUND)).replace("{time}", _hm(when, lang))}')
        band = ui.band(t(T("Trade the news with a plan.","Trade les nouvelles avec un plan.","Opera las noticias con un plan.")), t(why),
                       ui.btn(t(T("The economic calendar in Sweep","Le calendrier économique dans Sweep","El calendario económico en Sweep")), href(lang,"economic-calendar.html"), "line"))
        b = (ui.sec(nx + tbl + f'<p class="fine" style="margin-top:16px">{t(note)}</p>', "t", "dates", width="read")
             + ui.sec(f'<article class="article">{art}</article>', "n", "explained", width="read")
             + ui.sec(band + others, "t", "plan") + NEXT_JS)
        ld = jsonld({"@context":"https://schema.org","@type":"ItemList","name":t(T(f"{ti} release dates",f"Dates {of}",f"Fechas {of}")),
                     "itemListElement":[{"@type":"ListItem","position":i+1,"name":f'{ti} {e["date"]} {e["time"]} ET'} for i,e in enumerate(evs) if e["date"] >= TODAY_ISO][:12]})
        return (t(T(f"{ti} release dates 2026 and 2027 (ET) · Sweep",f"Dates {of} 2026 et 2027 (heure de New York) · Sweep",f"Fechas {of} 2026 y 2027 (hora de Nueva York) · Sweep")),
                t(T(f"Every {ti} release date and time for 2026 and 2027 in New York time, with the next release and what it means for futures traders.",
                    f"Toutes les dates et heures de publication {of} pour 2026 et 2027, en heure de New York, avec la prochaine publication et son effet sur les futures.",
                    f"Todas las fechas y horas de publicación {of} para 2026 y 2027, en hora de Nueva York, con el próximo dato y lo que significa para los futuros.")),
                hero + b + ui.final(lang, t), ld)
    return page

# the next release and the past dates, picked in the browser in New York time (the build's choice ages with the page)
NEXT_JS = """<script>(function(){var p={};new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).formatToParts(new Date()).forEach(function(x){p[x.type]=x.value});
var now=p.year+'-'+p.month+'-'+p.day+'T'+p.hour+':'+p.minute,nx=null;
document.querySelectorAll('[data-d]').forEach(function(r){var past=r.getAttribute('data-d')<now;r.classList.toggle('past',past);if(!past&&!nx)nx=r;});
var w=document.querySelector('[data-nx="when"]'),s=document.querySelector('[data-nx="st"]');
if(nx&&w){w.textContent=nx.querySelector('th').textContent+' · '+nx.querySelector('td').textContent;var st=nx.querySelector('.st');s.textContent=st.textContent;s.className=st.className;}
document.querySelectorAll('[data-next]').forEach(function(el){var l=JSON.parse(el.getAttribute('data-next'));for(var i=0;i<l.length;i++)if(l[i][0]>=now){el.textContent=l[i][1];return;}});})();</script>"""

HUB_HELP = T("""<h2>Which releases matter most</h2><ul>
<li><b>Inflation:</b> <a href="@cpi-release-dates.html">CPI</a>, <a href="@ppi-release-dates.html">PPI</a> and <a href="@pce-release-dates.html">PCE</a> shape what the market expects from the Fed. CPI usually moves futures the most.</li>
<li><b>Jobs:</b> the <a href="@nfp-release-dates.html">Nonfarm Payrolls</a> report, on the first Friday of most months.</li>
<li><b>The Fed:</b> <a href="@fomc-meeting-dates.html">FOMC</a> decisions, eight times a year, with a press conference.</li>
<li><b>Growth and spending:</b> <a href="@gdp-release-dates.html">GDP</a>, <a href="@retail-sales-release-dates.html">retail sales</a> and the <a href="@ism-manufacturing-release-dates.html">ISM manufacturing PMI</a>.</li></ul>
<h2>Release times</h2><p>Most U.S. data comes out at 8:30 a.m. New York time, an hour before the stock market opens. ISM comes out at 10:00 a.m., during the session, and FOMC decisions at 2:00 p.m. The <a href="@futures-market-hours.html">market hours page</a> converts these times to yours.</p>
<h2>Plan your week</h2><p>On Sunday, look at the week’s releases and write their times in your trading plan. For each one, decide in advance whether you trade it, wait for the first move to settle, or stay out, and keep the same choice every time: your journal can then tell you which works for you.</p>
<h2>What the statuses mean</h2><p><b>Official</b> dates come from the calendars the agencies publish. <b>Tentative</b> dates are announced but can still move. <b>Estimated</b> dates are projected from the usual pattern and are replaced once the agency publishes its schedule: check them again closer to the date.</p>""",
"""<h2>Les annonces qui comptent le plus</h2><ul>
<li><b>Inflation :</b> le <a href="@cpi-release-dates.html">CPI</a>, le <a href="@ppi-release-dates.html">PPI</a> et le <a href="@pce-release-dates.html">PCE</a> façonnent ce que le marché attend de la Fed. C’est en général le CPI qui fait le plus bouger les futures.</li>
<li><b>Emploi :</b> le rapport <a href="@nfp-release-dates.html">Nonfarm Payrolls</a>, le premier vendredi de la plupart des mois.</li>
<li><b>La Fed :</b> les décisions du <a href="@fomc-meeting-dates.html">FOMC</a>, huit fois par année, avec une conférence de presse.</li>
<li><b>Croissance et consommation :</b> le <a href="@gdp-release-dates.html">PIB</a>, les <a href="@retail-sales-release-dates.html">ventes au détail</a> et l’<a href="@ism-manufacturing-release-dates.html">ISM manufacturier</a>.</li></ul>
<h2>Heures de publication</h2><p>La plupart des données américaines sortent à 8 h 30, heure de New York, une heure avant l’ouverture de la bourse. L’ISM sort à 10 h, pendant la séance, et les décisions du FOMC à 14 h. La <a href="@futures-market-hours.html">page des heures de marché</a> convertit ces heures en la tienne.</p>
<h2>Planifie ta semaine</h2><p>Le dimanche, regarde les annonces de la semaine et note leurs heures dans ton plan de trading. Pour chacune, décide d’avance si tu la trades, si tu attends que le premier mouvement se calme, ou si tu restes à l’écart, et garde le même choix chaque fois : ton journal pourra alors te dire ce qui marche pour toi.</p>
<h2>Ce que veulent dire les statuts</h2><p>Les dates <b>officielles</b> viennent des calendriers publiés par les agences. Les dates <b>provisoires</b> sont annoncées mais peuvent encore bouger. Les dates <b>estimées</b> sont projetées selon le calendrier habituel et sont remplacées dès que l’agence publie le sien : revérifie-les à l’approche.</p>""",
"""<h2>Los datos que más cuentan</h2><ul>
<li><b>Inflación:</b> el <a href="@cpi-release-dates.html">CPI</a>, el <a href="@ppi-release-dates.html">PPI</a> y el <a href="@pce-release-dates.html">PCE</a> marcan lo que el mercado espera de la Fed. El CPI suele ser el que más mueve los futuros.</li>
<li><b>Empleo:</b> el informe <a href="@nfp-release-dates.html">Nonfarm Payrolls</a>, el primer viernes de la mayoría de los meses.</li>
<li><b>La Fed:</b> las decisiones del <a href="@fomc-meeting-dates.html">FOMC</a>, ocho veces al año, con rueda de prensa.</li>
<li><b>Crecimiento y consumo:</b> el <a href="@gdp-release-dates.html">PIB</a>, las <a href="@retail-sales-release-dates.html">ventas minoristas</a> y el <a href="@ism-manufacturing-release-dates.html">ISM manufacturero</a>.</li></ul>
<h2>Horas de publicación</h2><p>La mayoría de los datos de EE. UU. salen a las 8:30 hora de Nueva York, una hora antes de la apertura de la bolsa. El ISM sale a las 10:00, en plena sesión, y las decisiones del FOMC a las 14:00. La <a href="@futures-market-hours.html">página de horarios</a> convierte estas horas a la tuya.</p>
<h2>Planifica tu semana</h2><p>El domingo, mira los datos de la semana y apunta sus horas en tu plan de trading. Para cada uno, decide de antemano si lo operas, si esperas a que se calme el primer movimiento o si te quedas fuera, y mantén la misma decisión cada vez: así tu diario podrá decirte qué te funciona.</p>
<h2>Qué significan los estados</h2><p>Las fechas <b>oficiales</b> vienen de los calendarios que publican las agencias. Las <b>provisionales</b> están anunciadas pero aún pueden cambiar. Las <b>estimadas</b> se proyectan según el patrón habitual y se sustituyen cuando la agencia publica el suyo: vuelve a revisarlas cuando se acerque la fecha.</p>""")

def page_release_hub(lang, t):
    hero = ui.hero(t, T("Economic calendar","Calendrier économique","Calendario económico"), T("U.S. economic release dates.","Dates des annonces économiques américaines.","Fechas de los datos económicos de EE. UU."),
        T("The high-impact releases futures traders plan around, with every date for 2026 and 2027.","Les annonces importantes autour desquelles les traders de futures planifient, avec toutes les dates 2026 et 2027.","Los datos importantes que los traders de futuros tienen en cuenta, con todas las fechas de 2026 y 2027."))
    cards = []
    for k, sl, names, title, what, src in REL:
        up = [e for e in sorted([e for e in _EV if e["event"] in names], key=lambda e: (e["date"], e["time"])) if e["date"] >= TODAY_ISO]
        lab = lambda e: f'{t(T("Next","Prochaine","Próxima"))} : {_date(t,e["date"])} · {e["time"]} ET'.replace(" : ", ": " if lang != "fr" else " : ")
        nx = (f'<div class="more"><span class="go num" data-next="{_html.escape(json.dumps([[e["date"] + "T" + e["time"], lab(e)] for e in up[:8]], ensure_ascii=False))}">{lab(up[0])}</span></div>') if up else ""
        cards.append(ui.Card("text", f'<a class="card lift" href="{href(lang,sl)}"><h3>{_name(t, title)}</h3><p>{t(what)}</p>{nx}</a>'))
    b = (ui.sec(ui.cards(cards, 4), "t", "releases")
         + ui.sec(f'<article class="article">{localize(lang, t(HUB_HELP))}</article>', "n", "read", width="read") + NEXT_JS)
    return (t(T("Economic release dates 2026–2027: CPI, NFP, FOMC · Sweep","Annonces économiques 2026–2027 : CPI, NFP, FOMC · Sweep","Fechas de datos económicos 2026–2027: CPI, NFP, FOMC · Sweep")),
            t(T("Release dates and times for CPI, NFP, FOMC, PPI, PCE, retail sales, GDP and ISM in 2026 and 2027, in New York time, with the next release.","Dates et heures de CPI, NFP, FOMC, PPI, PCE, ventes au détail, PIB et ISM en 2026 et 2027, en heure de New York, avec la prochaine.","Fechas y horas de CPI, NFP, FOMC, PPI, PCE, ventas minoristas, PIB e ISM en 2026 y 2027, en hora de Nueva York, con el próximo dato.")),
            hero + b + ui.final(lang, t), "")
SYSTEM_PAGES.add("release-dates.html")

